    """
    Synchronous client for the HotPotato API.

    Usage::

        client = HotPotatoClient(api_key="your_key")
        result = client.classify(text="some input")
    """

    BASE_URL = "https://api.hotpotato.io/v3"
    DEFAULT_TIMEOUT = 30

    def __init__(self, api_key: str, timeout: int = DEFAULT_TIMEOUT):
        self.api_key = api_key
        self.timeout = timeout
        self._session_token: Optional[str] = None

    def _sign_request(self, body: bytes, secret: str) -> str:
        return hmac.new(secret.encode(), body, hashlib.sha256).hexdigest()

    def _request(self, method: str, path: str, payload: Optional[Dict] = None) -> Dict:
        url = self.BASE_URL + path
        data = json.dumps(payload).encode() if payload else None
        req = urllib.request.Request(url, data=data, method=method)
        req.add_header("Authorization", f"Bearer {self.api_key}")
        req.add_header("Content-Type", "application/json")
        with urllib.request.urlopen(req, timeout=self.timeout) as resp:
            return json.loads(resp.read())

    def classify(self, text: str, context: Optional[str] = None) -> Dict[str, Any]:
        """Classify a text string and return label + confidence."""
        return self._request("POST", "/classify", {"text": text, "context": context})

